mapper.select:
/* isry.sample.mapper.createmapper.selectCreateBoardList 공통팀 유민상*/ SELECT NTABRD_ESNTAL_NO , NTABRD_NM , UNT_TASKWK_SE_CD , NTABRD_TYPE_SE_CD , RDCNT_INDCT_YN , BBSCTT_RLS_TYPE_NM , IMPRTN_NTC_YN , USE_YN , NTABRD_DSCRP_CN , ATCMFL_SIZEA_MXMM_SZ , CMNT_LMT_CHARAC_CNT , CMNT_INDCT_PRVSON_NM FROM SBA000 WHERE 1=1 AND NVL(DEL_YN, 'N') != 'Y' AND SUBSTR(NTABRD_ESNTAL_NO, 1, 1) = '1'
AND NTABRD_NM LIKE '%' || #{NTABRD_NM} || '%'
AND NTABRD_TYPE_SE_CD = #{NTABRD_TYPE_SE_CD}
AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
ORDER BY UNT_TASKWK_SE_CD, NTABRD_ESNTAL_NO

mapper.insert:


			  SELECT LPAD(LPAD(SBA000_SQ01.NEXTVAL , 4 ,  '0'), 5, '1') AS NTABRD_ESNTAL_NO
                FROM DUAL



		/* isry.sample.mapper.createmapper.insertCreateBoardList 공통팀 유민상 */
		INSERT INTO SBA000(
		      NTABRD_ESNTAL_NO

			, UNT_TASKWK_SE_CD


			, NTABRD_NM


			, NTABRD_TYPE_SE_CD


			, USE_YN


			, NTABRD_DSCRP_CN


            , RDCNT_INDCT_YN


            , ATCMFL_SIZEA_MXMM_SZ


            , CMNT_LMT_CHARAC_CNT

            , BBSCTT_RLS_TYPE_NM
            , IMPRTN_NTC_YN           
            , CMNT_INDCT_PRVSON_NM              
		    , DEL_YN
		    , FRST_RGTR_ID    
            , FRST_REG_DT       
            , LAST_MDFR_ID
            , LAST_MDFCN_DT 
		)VALUES(
              #{NTABRD_ESNTAL_NO}

			, #{UNT_TASKWK_SE_CD}


			, #{NTABRD_NM}


			, #{NTABRD_TYPE_SE_CD}


			, #{USE_YN}


			, #{NTABRD_DSCRP_CN}


            , #{RDCNT_INDCT_YN}


            , #{ATCMFL_SIZEA_MXMM_SZ}


            , #{CMNT_LMT_CHARAC_CNT}

            , #{BBSCTT_RLS_TYPE_NM}
            , #{IMPRTN_NTC_YN}    
            , #{CMNT_INDCT_PRVSON_NM}        
		    , 'N'
		    , #{FRST_RGTR_ID}
            , SYSDATE
            , #{LAST_MDFR_ID}
            , SYSDATE   
		)

mapper.update:
		/* isry.sample.mapper.createmapper.updateCreateBoardList 공통팀 유민상 */
		UPDATE SBA000 SET


			NTABRD_NM = #{NTABRD_NM}


			, UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}


			, NTABRD_TYPE_SE_CD = #{NTABRD_TYPE_SE_CD}


			, USE_YN = #{USE_YN}


			, NTABRD_DSCRP_CN = #{NTABRD_DSCRP_CN}


            , RDCNT_INDCT_YN = #{RDCNT_INDCT_YN}


            , ATCMFL_SIZEA_MXMM_SZ = #{ATCMFL_SIZEA_MXMM_SZ}


            , CMNT_LMT_CHARAC_CNT = #{CMNT_LMT_CHARAC_CNT}


            , CMNT_INDCT_PRVSON_NM = #{CMNT_INDCT_PRVSON_NM}

            , BBSCTT_RLS_TYPE_NM = #{BBSCTT_RLS_TYPE_NM}
            , IMPRTN_NTC_YN = #{IMPRTN_NTC_YN}    
		    , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
		WHERE 1=1
		AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO__origin}

/* isry.sample.mapper.createmapper.deleteCreateBoardList 공통팀 유민상 */
UPDATE SBA000 SET
      DEL_YN = 'Y'
    , LAST_MDFCN_DT = SYSDATE       
    , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE 1=1
AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO__origin}

mapper.insert:
		/* isry.sample.mapper.createmapper.insertColInfoCreateBoardList 공통팀 유민상 */
		INSERT INTO SBA100(
              NTABRD_ESNTAL_NO
            , NTABRD_COL_ESNTAL_ID

			, NTABRD_COL_NM


			, NTABRD_COL_TYPE_NM

		  , NTABRD_TMPT_SE_CD
		  , NTABRD_COL_SRTNG_SQNCE		
		  , LIST_CONTRO_SIZEA_SZ		

			, ESNTL_YN


			, CMMNS_CD_ID


			, WDTH_MXMM_PLACEM_YN

            , WDTH_SZ

			, COL_PLACEM_INFO_CN


            , COL_BASS_VALUE

		    , INQ_CND_USE_YN
		    , DEL_YN		    
            , FRST_RGTR_ID    
            , FRST_REG_DT       
            , LAST_MDFR_ID
            , LAST_MDFCN_DT
		)VALUES(
		      #{NTABRD_ESNTAL_NO}
		    , (SELECT NVL(MAX(TO_NUMBER(NTABRD_COL_ESNTAL_ID)),0) +1 AS NTABRD_COL_ESNTAL_ID FROM SBA100 WHERE NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO})

			, #{NTABRD_COL_NM}


			, #{NTABRD_COL_TYPE_NM}

		    , #{NTABRD_TMPT_SE_CD}
            , #{NTABRD_COL_SRTNG_SQNCE}
            , #{LIST_CONTRO_SIZEA_SZ}		

			, #{ESNTL_YN}


			, #{CMMNS_CD_ID}


			, #{WDTH_MXMM_PLACEM_YN}

            , #{WDTH_SZ}

			, #{COL_PLACEM_INFO_CN}


            , #{COL_BASS_VALUE}

		    , 'N'
		    , 'N'
            , #{FRST_RGTR_ID}
            , SYSDATE
            , #{LAST_MDFR_ID}
            , SYSDATE 
		)

mapper.update:
		/* isry.sample.mapper.createmapper.updateColInfoCreateBoardList 공통팀 유민상 */
		UPDATE SBA100 SET


              NTABRD_COL_NM = #{NTABRD_COL_NM}


			, NTABRD_COL_TYPE_NM = #{NTABRD_COL_TYPE_NM}

            , NTABRD_COL_SRTNG_SQNCE = #{NTABRD_COL_SRTNG_SQNCE}
            , LIST_CONTRO_SIZEA_SZ = #{LIST_CONTRO_SIZEA_SZ}		

			, ESNTL_YN = #{ESNTL_YN}

			, CMMNS_CD_ID = #{CMMNS_CD_ID}

			, WDTH_MXMM_PLACEM_YN = #{WDTH_MXMM_PLACEM_YN}

		    , WDTH_SZ = #{WDTH_SZ}

			, COL_PLACEM_INFO_CN = #{COL_PLACEM_INFO_CN}


            , COL_BASS_VALUE = #{COL_BASS_VALUE}

            , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
		WHERE 1=1
		AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO__origin}
		AND NTABRD_COL_ESNTAL_ID = #{NTABRD_COL_ESNTAL_ID__origin}

/* isry.sample.mapper.createmapper.deleteColInfoCreateBoardList 공통팀 유민상 */
UPDATE SBA100 SET       
      DEL_YN = 'Y'
    , LAST_MDFCN_DT = SYSDATE     
    , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE 1=1
AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO__origin}
AND NTABRD_COL_ESNTAL_ID = #{NTABRD_COL_ESNTAL_ID__origin}

